# Shell completions, generated by the tools themselves and cached in
# ~/.cache/zsh/completions. A cache is regenerated when the binary changes
# (new path or mtime, e.g. after a brew upgrade). Tools that aren't
# installed are skipped. Force a refresh with: rm -rf ~/.cache/zsh/completions

zmodload -F zsh/stat b:zstat

_cached_completion() {
  local cmd=$1; shift
  (( $+commands[$cmd] )) || return 0

  local dir=${XDG_CACHE_HOME:-$HOME/.cache}/zsh/completions
  local cache=$dir/_$cmd bin=${commands[$cmd]:A} mtime key
  zstat -A mtime +mtime -- $bin 2>/dev/null
  key="$bin:$mtime"

  if [[ ! -s $cache || "$(<$cache.key 2>/dev/null)" != "$key" ]]; then
    mkdir -p $dir
    "$@" >| $cache.tmp 2>/dev/null && [[ -s $cache.tmp ]] || { rm -f $cache.tmp; return 0; }
    mv -f $cache.tmp $cache
    print -r -- $key >| $cache.key
  fi
  source $cache
}

_cached_completion kubectl  kubectl completion zsh
_cached_completion talosctl talosctl completion zsh
_cached_completion sops     sops completion zsh
_cached_completion flux     flux completion zsh
_cached_completion limactl  limactl completion zsh
unfunction _cached_completion

(( $+commands[fzf] )) && eval "$(fzf --zsh)"

# bao uses bash-style completion
if (( $+commands[bao] )); then
  autoload -U +X bashcompinit && bashcompinit
  complete -o nospace -C ${commands[bao]} bao
fi
